      input = _parseInputList(entry.value);
      continue;
    }
    if (key == 'thinkingLevel') {
      thinkingLevel = _parseThinkingLevel(entry.value);
      continue;
    }
    final value = entry.value;
    if (value is! String) {
      throw ConfigException(
        'FA_PROVIDER_CONFIG key "$key" must be a string, got: $value',
      );
    }
