/// loud naming the variable.
String? _resolveTwin(
  String name,
  String? plain,
  String twinName,
  String? twin,
) {
  final plainSet = plain != null && plain.trim().isNotEmpty;
  final twinSet = twin != null && twin.trim().isNotEmpty;
