    spec: spec,
    name: name,
    baseUrl: config.values['baseUrl']!,
    modelId: config.values['model']!,
    apiKeyEnvVar: keyVar,
    apiKey: [REDACTED:Sensitive Value],
    input: config.input,
    thinkingLevel: config.thinkingLevel,
