      endpointMaxTokens != override!.maxTokens) {
    notes.add(
      'capability override wins over the endpoint report for '
      '$provider/$modelId maxTokens: ${override.maxTokens} '
      '(endpoint reported $endpointMaxTokens)',
    );
  }
  return (resolvedMaxTokens, notes);
