+    final key = entry.key as String;
+    if (!_supportedConfigKeys.contains(key)) {
+      throw ConfigException(
+        'unknown FA_PROVIDER_CONFIG key: "$key" — supported keys: '
+        '${_supportedConfigKeys.join(', ')}',
+      );
