220:  String name,
221:  String? plain,
222:  String twinName,
223:  String? twin,
224:) {
225:  final plainSet = plain != null && plain.trim().isNotEmpty;
226:  final twinSet = twin != null && twin.trim().isNotEmpty;
227:  if (!plainSet && !twinSet) return null;
228:  if (!twinSet) return plain;
229:  final decoded = _decodeBase64(twinName, twin);
230:  if (!plainSet) return decoded;
231:  if (plain != decoded) {
232:    throw ConfigException(
233:      '$name and $twinName are both set with different values — ambiguous; '
234:      'set only one (when both carry the same value either may be used)',
