int? _parseCapabilityInt(String key, Object? value) {
  if (value == null) return null;
  if (value is String && value.trim().isEmpty) return null;
  if (value is! int) {
    throw ConfigException(
      'FA_PROVIDER_CONFIG "$key" must be an integer, got: $value',
