  }
  final floor = key == 'contextWindow'
      ? minOverrideContextWindow
      : minOverrideMaxTokens;
  if (value < floor) {
    throw ConfigException(
      'FA_PROVIDER_CONFIG "$key" must be at least $floor '
      '(the ${key == 'contextWindow' ? 'compaction reserve' : 'answer budget'}'
      ' floor), got: $value',
    );
  }
  return value;
}
